export const PNG_COPY_ACTION_SELECTOR =
  '[data-template-slide-png-copy-action="true"]';
export const TEMPLATE_SLIDE_SELECTOR = '[data-testid^="template-slide-"]';
export const HYDRATED_PNG_COPY_ATTR = 'data-hydrated-png-copy';
export const TEMPLATE_SLIDE_TEST_ID_PREFIX = 'template-slide-';
export const PNG_COPY_FEEDBACK_ID_PREFIX = 'template-slide-png-copy-feedback';

export const stripPngCopyActions = (root: ParentNode): void => {
  root
    .querySelectorAll(PNG_COPY_ACTION_SELECTOR)
    .forEach((node) => node.remove());
};

export const stripPngCopyActionsFromHtml = (html: string): string => {
  const template = document.createElement('template');
  template.innerHTML = html;
  stripPngCopyActions(template.content);
  return template.innerHTML;
};
